const tolerance = (name: string) => (name.startsWith('docstring') ? 6e-4 : 2e-5)

describe('numbers against NumPy, SciPy, OpenCV, scikit-learn and the Keras docstrings', () => {
  it.each(CASES)('%s', (name, code, expected) => {
    const r = run(`${H}${code}\nprint(np.array(out).ravel().tolist())`)
    expect(r.error).toBeNull()
    const got = JSON.parse(r.stdout.trim().replace(/True/g, '1').replace(/False/g, '0')) as number[]
    expect(got.length).toBe(expected.length)
    got.forEach((g, i) => expect(Math.abs(g - expected[i])).toBeLessThanOrEqual(tolerance(name) * Math.max(1, Math.abs(expected[i]))))
  })
})

// The formulas are the ones lecture notes teach and the Keras sources state; each comment shows the sum.
